      "path": "src/index.ts",
      "content": "import { homedir } from 'node:os'\nimport { join } from 'node:path'\nimport { readFile } from 'node:fs/promises'\nimport { existsSync } from 'node:fs'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { Config, type Config as ConfigShape } from './config.js'\nimport { Attribution } from './attribution.js'\nimport { Pricing } from './pricing.js'\nimport { UsageStore } from './store.js'\nimport { Quota } from './quota.js'\nimport { createReportTool } from './report.js'\nimport { createTeamCostService } from './service.js'\nimport type { UsageRecord, QuotaStatus } from './types.js'\n\nexport const name = 'dsh-team-cost'\n\n/** The tool registry is required for the report tool. */\nexport const inject = ['tools']\n\nexport { Config }\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Events {\n    /** Fired when a member crosses any configured budget (100%). */\n    'dsh-team-cost/quota-exceeded': (payload: QuotaStatus) => void\n  }\n}\n\n/** dsh-login's home resolution: DSH_HOME env, else ~/.dsh. */\nfunction resolveDshHome(): string {\n  const env = process.env.DSH_HOME\n  return env !== undefined && env.length > 0 ? env : join(homedir(), '.dsh')\n}\n\n/**\n * Team cost captain for DeepSeek Harness.\n *\n * - Meters every model call from the `session/event` firehose\n *   (`assistant/message` events carry the step's TokenUsage), subagents\n *   included: any session that reports usage is metered.\n * - Attributes each call to a team member via workspace-prefix rules.\n * - Prices the call against the builtin DeepSeek 2026-09 catalog or user\n *   overrides, and appends the record to a monthly JSONL log.\n * - Evaluates member budgets, alerts thresholds via webhook, and can block\n *   new model requests in enforce mode.\n */\nexport function apply(ctx: Context, config: ConfigShape): void {\n  if (!config.enabled) return\n\n  const dataDir = config.dataDir === '' ? join(resolveDshHome(), '.dsh-team-cost') : config.dataDir\n  const onError = (err: unknown): void => {\n    ctx.logger.warn(err instanceof Error ? err.message : String(err))\n  }\n\n  const store = new UsageStore(dataDir, config.flushIntervalSec)\n  const attribution = new Attribution(config.attributionRules, config.defaultMember)\n  const pricing = new Pricing(config.currency, config.deepseekPeakPricing)\n  const quota = new Quota(dataDir, store, config.alertThresholds.map(Number), config.alertWebhook, onError)\n\n  const loadOverrides = async (): Promise<void> => {\n    const file = join(dataDir, 'price-overrides.json')\n    if (!existsSync(file)) return\n    try {\n      pricing.setOverrides(JSON.parse(await readFile(file, 'utf8')))\n    } catch (err) {\n      onError(err)\n    }\n  }\n\n  void store\n    .init()\n    .then(loadOverrides)\n    .then(() => {\n      store.startFlushing(onError)\n      quota.start()\n    })\n    .catch(onError)\n\n  ctx.effect(() => () => {\n    void store.dispose()\n    quota.dispose()\n  })\n\n  // Meter one usage-bearing assistant message. The firehose delivers every\n  // session — top-level or subagent — so team and teammate spend is counted\n  // in full instead of being lost to single-session dashboards.\n  ctx.on('session/event', (session, event) => {\n    if (event.type !== 'assistant/message') return\n    const usage = event.data.usage\n    if (!usage) return\n    const source = event.data.message.source\n    const header = session.header\n    const user = attribution.resolve(header.cwd)\n    const record: UsageRecord = {\n      t: new Date(event.time).toISOString(),\n      seq: event.seq,\n      sid: header.id,\n      ws: header.cwd ?? '',\n      user,\n      provider: source.provider,\n      model: source.model,\n      in: usage.inputTokens ?? 0,\n      out: usage.outputTokens ?? 0,\n      cr: usage.cacheReadTokens,\n      cw: usage.cacheWriteTokens,\n      rz: usage.reasoningTokens,\n      cost: Number(pricing.cost(source.model, usage).toFixed(6)),\n    }\n    void store\n      .record(record)\n      .then(() => quota.evaluate(user))\n      .then((status) => {\n        if (status.over) ctx.emit('dsh-team-cost/quota-exceeded', status)\n      })\n      .catch(onError)\n  })\n\n  if (config.enforce !== 'off') {\n    ctx.on('agent/request', (payload, next) => {\n      if (config.enforce === 'total') {\n        if (config.totalDailyCost > 0) {\n          const totals = store.totalsFor('*')\n          if (totals.todayCost >= config.totalDailyCost) {\n            throw new Error(\n              `[dsh-team-cost] 团队今日费用已超预算 ${totals.todayCost.toFixed(2)}/${config.totalDailyCost} ${config.currency}，新请求已被拦截`,\n            )\n          }\n        }\n      } else if (config.enforce === 'members') {\n        // Best-effort member resolution from the agent's session header.\n        const agent = payload.agent as { session?: { header?: { cwd?: string } } } | undefined\n        const user = attribution.resolve(agent?.session?.header?.cwd)\n        if (quota.isBlocked(user)) {\n          throw new Error(\n            `[dsh-team-cost] 成员 ${user} 已超出预算，新请求已被拦截（调整 <dataDir>/members.json 后一分钟内生效）`,\n          )\n        }\n      }\n      return next()\n    })\n  }\n\n  ctx.tools.register(createReportTool({ store, currency: config.currency }))\n\n  // RPC 服务:Web 看板经 remote.teamCost.getState() 读取快照(./typert 清单由\n  // typert-loader 自动扫描注册)。\n  ctx.provide(\n    'teamCost',\n    createTeamCostService({ store, quota, currency: config.currency, enforce: config.enforce }),\n  )\n}\n"
    },
