      "path": "src/store.ts",
      "content": "import { appendFile, mkdir, readFile, rename, writeFile } from 'node:fs/promises'\nimport { existsSync } from 'node:fs'\nimport { join } from 'node:path'\nimport type { RollupCell, UsageRecord } from './types.js'\n\nfunction pad2(n: number): string {\n  return String(n).padStart(2, '0')\n}\n\n/** Local-time day key (YYYY-MM-DD) — must match `todayKey()`. */\nfunction dayKeyOf(iso: string): string {\n  const d = new Date(iso)\n  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`\n}\n\nfunction monthKeyOf(iso: string): string {\n  return dayKeyOf(iso).slice(0, 7)\n}\n\n/**\n * Append-only JSONL metering log plus an in-memory aggregate, flushed to a\n * small JSON file for fast startup. The JSONL file is the source of truth;\n * rollups.json is a cache and is rebuilt from it on demand.\n */\nexport class UsageStore {\n  private cells = new Map<string, RollupCell>()\n  private flushTimer: ReturnType<typeof setInterval> | undefined\n\n  constructor(\n    private readonly dataDir: string,\n    private flushIntervalSec: number,\n  ) {}\n\n  async init(): Promise<void> {\n    await mkdir(this.dataDir, { recursive: true })\n    await mkdir(join(this.dataDir, 'exports'), { recursive: true })\n    await this.loadRollups()\n  }\n\n  startFlushing(onError?: (err: unknown) => void): void {\n    const sec = Math.max(5, this.flushIntervalSec)\n    this.flushTimer = setInterval(() => {\n      this.flush().catch((err) => onError?.(err))\n    }, sec * 1000)\n    this.flushTimer.unref?.()\n  }\n\n  async dispose(): Promise<void> {\n    if (this.flushTimer) clearInterval(this.flushTimer)\n    await this.flush()\n  }\n\n  private jsonlPath(iso: string): string {\n    return join(this.dataDir, `usage-${monthKeyOf(iso)}.jsonl`)\n  }\n\n  private get rollupsPath(): string {\n    return join(this.dataDir, 'rollups.json')\n  }\n\n  async record(rec: UsageRecord): Promise<void> {\n    await appendFile(this.jsonlPath(rec.t), JSON.stringify(rec) + '\\n', 'utf8')\n    const key = `${dayKeyOf(rec.t)}\\u0000${rec.user}\\u0000${rec.model}`\n    let cell = this.cells.get(key)\n    if (!cell) {\n      cell = { day: dayKeyOf(rec.t), user: rec.user, model: rec.model, calls: 0, in: 0, out: 0, cr: 0, cw: 0, cost: 0 }\n      this.cells.set(key, cell)\n    }\n    cell.calls += 1\n    cell.in += rec.in\n    cell.out += rec.out\n    cell.cr += rec.cr ?? 0\n    cell.cw += rec.cw ?? 0\n    cell.cost += rec.cost\n  }\n\n  private cellList(): RollupCell[] {\n    return [...this.cells.values()]\n  }\n\n  todayKey(): string {\n    const now = new Date()\n    const y = now.getFullYear()\n    const m = String(now.getMonth() + 1).padStart(2, '0')\n    const d = String(now.getDate()).padStart(2, '0')\n    return `${y}-${m}-${d}`\n  }\n\n  monthKey(): string {\n    return this.todayKey().slice(0, 7)\n  }\n\n  /** Aggregate rows over a range, grouped by 'member' | 'model' | 'day'. */\n  aggregate(range: 'today' | 'month' | 'all', groupBy: 'member' | 'model' | 'day'): RollupCell[] {\n    const today = this.todayKey()\n    const month = this.monthKey()\n    const acc = new Map<string, RollupCell>()\n    for (const cell of this.cellList()) {\n      if (range === 'today' && cell.day !== today) continue\n      if (range === 'month' && !cell.day.startsWith(month)) continue\n      const groupKey = groupBy === 'member' ? cell.user : groupBy === 'model' ? cell.model : cell.day\n      let row = acc.get(groupKey)\n      if (!row) {\n        row = { day: cell.day, user: groupBy === 'member' ? groupKey : '*', model: groupBy === 'model' ? groupKey : '*', calls: 0, in: 0, out: 0, cr: 0, cw: 0, cost: 0 }\n        acc.set(groupKey, row)\n      }\n      row.calls += cell.calls\n      row.in += cell.in\n      row.out += cell.out\n      row.cr += cell.cr\n      row.cw += cell.cw\n      row.cost += cell.cost\n    }\n    return [...acc.values()].sort((a, b) => b.cost - a.cost)\n  }\n\n  /** Totals for one member (or '*') over today and this month. */\n  totalsFor(user: string): { todayCost: number; todayTokens: number; monthCost: number; monthTokens: number } {\n    const today = this.todayKey()\n    const month = this.monthKey()\n    const out = { todayCost: 0, todayTokens: 0, monthCost: 0, monthTokens: 0 }\n    for (const cell of this.cellList()) {\n      if (user !== '*' && cell.user !== user) continue\n      const tokens = cell.in + cell.out + cell.cr + cell.cw\n      if (cell.day === today) {\n        out.todayCost += cell.cost\n        out.todayTokens += tokens\n      }\n      if (cell.day.startsWith(month)) {\n        out.monthCost += cell.cost\n        out.monthTokens += tokens\n      }\n    }\n    return out\n  }\n\n  async exportCsv(range: 'today' | 'month' | 'all'): Promise<string> {\n    const rows = this.aggregate(range, 'day')\n    const header = 'day,member,model,calls,input_tokens,output_tokens,cache_read,cache_write,cost\\n'\n    const lines = rows.map((r) => `${r.day},${r.user},${r.model},${r.calls},${r.in},${r.out},${r.cr},${r.cw},${r.cost.toFixed(6)}`)\n    const csv = header + lines.join('\\n') + '\\n'\n    const file = join(this.dataDir, 'exports', `report-${range}-${Date.now()}.csv`)\n    await writeFile(file, csv, 'utf8')\n    return file\n  }\n\n  private async flush(): Promise<void> {\n    const payload = JSON.stringify({ version: 1, cells: this.cellList() })\n    const tmp = this.rollupsPath + '.tmp'\n    await writeFile(tmp, payload, 'utf8')\n    await rename(tmp, this.rollupsPath)\n  }\n\n  private async loadRollups(): Promise<void> {\n    if (!existsSync(this.rollupsPath)) return\n    try {\n      const parsed: unknown = JSON.parse(await readFile(this.rollupsPath, 'utf8'))\n      const cells = (parsed as { cells?: RollupCell[] }).cells\n      if (Array.isArray(cells)) {\n        for (const cell of cells) {\n          if (cell && typeof cell.day === 'string' && typeof cell.user === 'string' && typeof cell.model === 'string') {\n            this.cells.set(`${cell.day}\\u0000${cell.user}\\u0000${cell.model}`, cell)\n          }\n        }\n      }\n    } catch {\n      // Corrupt cache: rebuild lazily is not implemented in MVP; keep going\n      // with in-memory only aggregates — the JSONL log still has everything.\n    }\n  }\n}\n"
    },
    {
      "path": "src/pricing.ts",
      "content": "import type { ModelPrice } from './types.js'\n\n/**\n * Price lookup and cost computation.\n *\n * Prices are currency units per million tokens with three components:\n * cache-hit input (cr), uncached input (in), output (out). Cache-write is\n * billed as uncached input (DeepSeek bills cache-write at the input rate).\n *\n * The builtin catalog ships DeepSeek's published 2026-09 pricing in both\n * CNY and USD, off-peak and peak. Unknown models are not guessed: they\n * meter tokens and price at `fallbackPrice` (default 0) until an override\n * is added to <dataDir>/price-overrides.json.\n */\n\nconst DEEPEEK_V4_FLASH: Record<'CNY' | 'USD', Record<'offpeak' | 'peak', ModelPrice>> = {\n  CNY: {\n    offpeak: { cr: 0.02, in: 1, out: 4 },\n    peak: { cr: 0.04, in: 2, out: 8 },\n  },\n  USD: {\n    offpeak: { cr: 0.003, in: 0.15, out: 0.6 },\n    peak: { cr: 0.006, in: 0.3, out: 1.2 },\n  },\n}\n\n/** Legacy DeepSeek chat/reasoner pricing, kept for older logs. */\nconst DEEPSEEK_LEGACY: Record<'CNY' | 'USD', ModelPrice> = {\n  CNY: { cr: 0.2, in: 2, out: 8 },\n  USD: { cr: 0.027, in: 0.27, out: 1.1 },\n}\n\nexport class Pricing {\n  private readonly overrides = new Map<string, ModelPrice>()\n\n  constructor(\n    private readonly currency: string,\n    private readonly peak: boolean,\n    private readonly fallback: ModelPrice = { cr: 0, in: 0, out: 0 },\n  ) {}\n\n  /** Load user overrides (model name → price). Later calls win. */\n  setOverrides(entries: Record<string, ModelPrice>): void {\n    this.overrides.clear()\n    for (const [model, price] of Object.entries(entries)) {\n      if (price && typeof price.in === 'number' && typeof price.out === 'number') {\n        this.overrides.set(model, price)\n      }\n    }\n  }\n\n  priceFor(model: string): { price: ModelPrice; source: 'override' | 'builtin' | 'fallback' } {\n    const override = this.overrides.get(model)\n    if (override) return { price: override, source: 'override' }\n    const cur = this.currency.toUpperCase() === 'USD' ? 'USD' : 'CNY'\n    const m = model.toLowerCase()\n    // DeepSeek route ids commonly look like deepseek-chat / deepseek-reasoner\n    // / deepseek-v4.x-flash; flash-family and legacy ids resolve separately.\n    if (m.startsWith('deepseek')) {\n      if (m.includes('flash') || m.includes('v4')) {\n        const tier = DEEPEEK_V4_FLASH[cur]\n        return { price: this.peak ? tier.peak : tier.offpeak, source: 'builtin' }\n      }\n      return { price: DEEPSEEK_LEGACY[cur], source: 'builtin' }\n    }\n    return { price: this.fallback, source: 'fallback' }\n  }\n\n  /** Cost in currency major units for one call. */\n  cost(\n    model: string,\n    usage: { inputTokens: number; outputTokens: number; cacheReadTokens?: number; cacheWriteTokens?: number },\n  ): number {\n    const { price } = this.priceFor(model)\n    const cr = usage.cacheReadTokens ?? 0\n    const cw = usage.cacheWriteTokens ?? 0\n    const m = 1e6\n    return (\n      (cr * price.cr) / m +\n      ((usage.inputTokens + cw) * price.in) / m +\n      (usage.outputTokens * price.out) / m\n    )\n  }\n}\n"
    },
    {
      "path": "src/attribution.ts",
      "content": "/** Member attribution: map a session workspace (cwd) to a team member. */\n\nexport interface AttributionRule {\n  member: string\n  prefix: string\n}\n\n/**\n * Parse `memberName=workspacePathPrefix` rules. Longest prefixes win;\n * malformed entries (no '=') are ignored so a typo cannot take the\n * metering plugin down.\n */\nexport function parseRules(entries: readonly string[]): AttributionRule[] {\n  const rules: AttributionRule[] = []\n  for (const entry of entries) {\n    const eq = entry.indexOf('=')\n    if (eq <= 0 || eq === entry.length - 1) continue\n    const member = entry.slice(0, eq).trim()\n    const prefix = entry.slice(eq + 1).trim()\n    if (member && prefix) rules.push({ member, prefix })\n  }\n  rules.sort((a, b) => b.prefix.length - a.prefix.length)\n  return rules\n}\n\n/** Normalize a path for comparison: forward slashes, no trailing slash. */\nfunction normalizePath(p: string): string {\n  return p.replaceAll('\\\\', '/').replace(/\\/+$/, '').toLowerCase()\n}\n\nexport class Attribution {\n  private readonly rules: AttributionRule[]\n\n  constructor(\n    entries: readonly string[],\n    private readonly defaultMember: string,\n  ) {\n    this.rules = parseRules(entries)\n  }\n\n  /** Resolve the member for one session cwd (may be empty/unknown). */\n  resolve(cwd: string | undefined): string {\n    if (!cwd) return this.defaultMember\n    const norm = normalizePath(cwd)\n    for (const rule of this.rules) {\n      if (norm.startsWith(normalizePath(rule.prefix))) return rule.member\n    }\n    return this.defaultMember\n  }\n}\n"
    },
    {
      "path": "src/quota.ts",
      "content": "import { readFile } from 'node:fs/promises'\nimport { existsSync } from 'node:fs'\nimport { join } from 'node:path'\nimport type { MembersFile, QuotaStatus } from './types.js'\nimport type { UsageStore } from './store.js'\n\nconst RELOAD_MS = 60_000\n\n/**\n * Member budgets + threshold alerts + optional enforcement.\n *\n * Budgets live in <dataDir>/members.json ({ \"members\": [{ name, dailyCost,\n * monthlyCost, dailyTokens, monthlyTokens }] }) and hot-reload every minute,\n * so admins edit the file without restarting DSH.\n */\nexport class Quota {\n  private members = new Map<string, { dailyCost?: number; monthlyCost?: number; dailyTokens?: number; monthlyTokens?: number }>()\n  private lastLoad = 0\n  private alerted = new Set<string>()\n  private reloadTimer: ReturnType<typeof setInterval> | undefined\n\n  constructor(\n    private readonly dataDir: string,\n    private readonly store: UsageStore,\n    private readonly thresholds: readonly number[],\n    private readonly webhook: string,\n    private readonly onError?: (err: unknown) => void,\n  ) {}\n\n  start(): void {\n    this.reloadTimer = setInterval(() => this.loadMembers().catch((e) => this.onError?.(e)), RELOAD_MS)\n    this.reloadTimer.unref?.()\n  }\n\n  dispose(): void {\n    if (this.reloadTimer) clearInterval(this.reloadTimer)\n  }\n\n  get membersPath(): string {\n    return join(this.dataDir, 'members.json')\n  }\n\n  async loadMembers(): Promise<void> {\n    this.lastLoad = Date.now()\n    if (!existsSync(this.membersPath)) return\n    try {\n      const parsed: unknown = JSON.parse(await readFile(this.membersPath, 'utf8'))\n      const file = parsed as MembersFile\n      if (Array.isArray(file.members)) {\n        this.members = new Map(file.members.map((m) => [m.name, m]))\n      }\n    } catch (err) {\n      this.onError?.(err)\n    }\n  }\n\n  private ensureFresh(): void {\n    if (Date.now() - this.lastLoad > RELOAD_MS) void this.loadMembers()\n  }\n\n  /** All configured member names (budget file order). */\n  memberNames(): string[] {\n    this.ensureFresh()\n    return [...this.members.keys()]\n  }\n\n  /** Budget lines for one member, or {} when unconfigured. */\n  budgetsFor(user: string): { dailyCost?: number; monthlyCost?: number; dailyTokens?: number; monthlyTokens?: number } {\n    this.ensureFresh()\n    const b = this.members.get(user)\n    if (!b) return {}\n    return { dailyCost: b.dailyCost, monthlyCost: b.monthlyCost, dailyTokens: b.dailyTokens, monthlyTokens: b.monthlyTokens }\n  }\n\n  /**\n   * Evaluate one metered call. Fires webhook alerts on newly crossed\n   * thresholds (per member+threshold, once per day) and returns the status.\n   */\n  async evaluate(user: string): Promise<QuotaStatus> {\n    this.ensureFresh()\n    const budget = this.members.get(user)\n    const totals = this.store.totalsFor(user)\n    const status: QuotaStatus = { user, level: 0, exceeded: [], over: false }\n    if (!budget) return status\n\n    const lines: Array<[string, number, number]> = [\n      ['dailyCost', budget.dailyCost ?? 0, totals.todayCost],\n      ['monthlyCost', budget.monthlyCost ?? 0, totals.monthCost],\n      ['dailyTokens', budget.dailyTokens ?? 0, totals.todayTokens],\n      ['monthlyTokens', budget.monthlyTokens ?? 0, totals.monthTokens],\n    ]\n    for (const [name, limit, value] of lines) {\n      if (!limit || limit <= 0) continue\n      const fraction = value / limit\n      if (fraction >= 1) {\n        status.over = true\n        status.exceeded.push(name)\n        status.level = Math.max(status.level, 1)\n        this.alertOnce(user, `${name}:100`, `成员 ${user} 已超出 ${name} 预算 (${Math.round(value)}/${limit})`)\n      } else {\n        for (const threshold of this.thresholds) {\n          if (threshold > 0 && threshold < 100 && fraction >= threshold / 100) {\n            status.level = Math.max(status.level, threshold / 100)\n            this.alertOnce(user, `${name}:${threshold}`, `成员 ${user} 用量已达 ${name} 预算的 ${threshold}% (${Math.round(value)}/${limit})`)\n          }\n        }\n      }\n    }\n    return status\n  }\n\n  /** True when new model requests for this member should be blocked. */\n  isBlocked(user: string): boolean {\n    this.ensureFresh()\n    const budget = this.members.get(user)\n    if (!budget) return false\n    const totals = this.store.totalsFor(user)\n    if ((budget.dailyCost ?? 0) > 0 && totals.todayCost >= (budget.dailyCost ?? 0)) return true\n    if ((budget.monthlyCost ?? 0) > 0 && totals.monthCost >= (budget.monthlyCost ?? 0)) return true\n    if ((budget.dailyTokens ?? 0) > 0 && totals.todayTokens >= (budget.dailyTokens ?? 0)) return true\n    if ((budget.monthlyTokens ?? 0) > 0 && totals.monthTokens >= (budget.monthlyTokens ?? 0)) return true\n    return false\n  }\n\n  private alertOnce(user: string, key: string, message: string): void {\n    const dedupe = `${user}:${new Date().toISOString().slice(0, 10)}:${key}`\n    if (this.alerted.has(dedupe)) return\n    this.alerted.add(dedupe)\n    const totals = this.store.totalsFor(user)\n    this.onError?.(new Error(`[dsh-team-cost] ${message}`))\n    if (this.webhook) {\n      const body = JSON.stringify({\n        plugin: 'dsh-team-cost',\n        user,\n        message,\n        todayCost: Number(totals.todayCost.toFixed(4)),\n        monthCost: Number(totals.monthCost.toFixed(4)),\n        time: new Date().toISOString(),\n      })\n      void fetch(this.webhook, {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body,\n      }).catch((err) => this.onError?.(err))\n    }\n  }\n}\n"
    },
    {
      "path": "src/report.ts",
      "content": "import { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { UsageStore } from './store.js'\n\nexport interface ReportDeps {\n  store: UsageStore\n  currency: string\n}\n\nconst RANGES = new Set(['today', 'month', 'all'])\nconst GROUPS = new Set(['member', 'model', 'day'])\n\nfunction fmt(n: number): string {\n  return n % 1 === 0 ? String(n) : n.toFixed(0)\n}\n\nexport function createReportTool(deps: ReportDeps) {\n  return defineTool({\n    name: 'team_cost_report',\n    description:\n      '查询团队 AI 用量与成本报表（按成员/模型/天分组，支持 today/month/all 范围，可导出 CSV）。' +\n      'Query team AI usage and cost: group by member, model, or day; optionally export CSV.',\n    parameters: {\n      range: { type: 'string', description: '统计范围: today | month | all (默认 today)' },\n      groupBy: { type: 'string', description: '分组维度: member | model | day (默认 member)' },\n      csv: { type: 'string', description: '传 \"true\" 时同时导出 CSV 文件并返回路径' },\n    },\n    output: {\n      schema: { type: 'string' },\n      render: (_args, value) => [{ type: 'text', text: value }],\n    },\n    async execute(args: { range?: string; groupBy?: string; csv?: string }) {\n      const range = RANGES.has(args.range ?? '') ? (args.range as 'today' | 'month' | 'all') : 'today'\n      const groupBy = GROUPS.has(args.groupBy ?? '') ? (args.groupBy as 'member' | 'model' | 'day') : 'member'\n      const rows = deps.store.aggregate(range, groupBy)\n      const label = groupBy === 'member' ? '成员' : groupBy === 'model' ? '模型' : '日期'\n      const lines: string[] = [\n        `团队用量报表 (${range === 'today' ? '今天' : range === 'month' ? '本月' : '全部'}, 单位: ${deps.currency})`,\n        '',\n        `${label} | 调用次数 | 输入 tokens | 输出 tokens | 缓存命中 | 费用`,\n        '--- | --- | --- | --- | --- | ---',\n      ]\n      let totalCost = 0\n      for (const row of rows) {\n        totalCost += row.cost\n        lines.push(\n          `${groupBy === 'day' ? row.day : groupBy === 'member' ? row.user : row.model} | ${row.calls} | ${fmt(row.in + row.cw)} | ${fmt(row.out)} | ${fmt(row.cr)} | ${row.cost.toFixed(4)}`,\n        )\n      }\n      lines.push('', `合计费用: ${totalCost.toFixed(4)} ${deps.currency}`)\n\n      if (args.csv === 'true') {\n        const file = await deps.store.exportCsv(range)\n        lines.push('', `CSV 已导出: ${file}`)\n      }\n      return lines.join('\\n')\n    },\n  })\n}\n"
    },
    {
      "path": "src/config.ts",
      "content": "import z from '@deepseek-ai/schemastery'\n\n/** Plugin configuration for the dsh-team-cost metering plugin. */\nexport interface Config {\n  /** Directory for data files (usage JSONL, rollups, members.json, exports).\n   * When empty, resolved to `<dshHome>/.dsh-team-cost` at apply time. */\n  dataDir: string\n  /** Whether metering is active (default true). When false, the plugin\n   * registers nothing. */\n  enabled: boolean\n  /** Currency for built-in prices and report labels: 'CNY' or 'USD'. */\n  currency: string\n  /** Use DeepSeek peak pricing instead of off-peak for the builtin catalog. */\n  deepseekPeakPricing: boolean\n  /**\n   * Enforcement mode:\n   * - 'off' (default): meter and alert only, never block model requests.\n   * - 'total': block new model requests once the TOTAL daily cost budget is\n   *   exceeded (set `totalDailyCost` > 0 to arm).\n   * - 'members': additionally block a member's new requests once that member\n   *   is over any of their 100% budgets. Member resolution inside the request\n   *   hook is best-effort (workspace-based); sessions that cannot be resolved\n   *   are allowed. Requires a DSH version whose agent payload exposes the\n   *   session; when it does not, 'members' behaves like 'off' for unresolved\n   *   agents — which is why 'off' remains the default.\n   */\n  enforce: string\n  /** Total daily cost budget across all members, in currency major units.\n   * 0 disables the total budget (default). Used by enforce='total'. */\n  totalDailyCost: number\n  /** Fractions that trigger an alert, e.g. 80 and 100. */\n  alertThresholds: string[]\n  /** Optional HTTP(S) endpoint receiving a JSON POST on every threshold\n   * crossing: { user, level, exceeded, todayCost, monthCost }. Empty\n   * disables webhook alerts. */\n  alertWebhook: string\n  /**\n   * Member attribution rules, tried longest-prefix first. Each rule is\n   * `memberName=workspacePathPrefix` (the member, '=', then the cwd prefix).\n   * Sessions whose cwd matches a prefix are attributed to that member.\n   * Unmatched sessions fall back to `defaultMember`. Tip: if you run\n   * dsh-login, add one rule per user workspace (its per-user sandbox root\n   * makes this a one-line mapping per member).\n   */\n  attributionRules: string[]\n  /** Member name for sessions that match no attribution rule. */\n  defaultMember: string\n  /** Flush rollups to disk every N seconds (default 15). */\n  flushIntervalSec: number\n}\n\nexport const Config: z<Config> = z.object({\n  dataDir: z.string().default(''),\n  enabled: z.boolean().default(true),\n  currency: z.string().default('CNY'),\n  deepseekPeakPricing: z.boolean().default(false),\n  enforce: z.string().default('off'),\n  totalDailyCost: z.natural().default(0),\n  alertThresholds: z.array(String).default(['80', '100']),\n  alertWebhook: z.string().default(''),\n  attributionRules: z.array(String).default([]),\n  defaultMember: z.string().default('unassigned'),\n  flushIntervalSec: z.natural().default(15),\n})\n"
    },
    {
      "path": "src/service.ts",
      "content": "import type { UsageStore } from './store.js'\nimport type { Quota } from './quota.js'\nimport type { GroupRow, MemberRow, TeamCostState } from './types.js'\n\n/**\n * The `teamCost` remote service consumed by the web dashboard through the\n * Typert gateway (`remote.teamCost.getState()`). Bound with a `typertRemote`\n * property so the gateway's validateBinding accepts the hand-written\n * `./typert` manifest.\n */\nexport function createTeamCostService(deps: {\n  store: UsageStore\n  quota: Quota\n  currency: string\n  enforce: string\n}): TeamCostService {\n  const { store, quota, currency, enforce } = deps\n\n  const service = {\n    /** Full dashboard snapshot: member rows with budgets/totals, model rows. */\n    async getState(): Promise<TeamCostState> {\n      const memberRows: MemberRow[] = []\n      const knownMembers = quota.memberNames()\n      const seen = new Set<string>(knownMembers)\n      for (const name of knownMembers) {\n        const totals = store.totalsFor(name)\n        const status = await quota.evaluate(name)\n        const budgets = quota.budgetsFor(name)\n        memberRows.push({\n          name,\n          todayCost: totals.todayCost,\n          todayTokens: totals.todayTokens,\n          monthCost: totals.monthCost,\n          monthTokens: totals.monthTokens,\n          dailyCost: budgets.dailyCost,\n          monthlyCost: budgets.monthlyCost,\n          dailyTokens: budgets.dailyTokens,\n          monthlyTokens: budgets.monthlyTokens,\n          level: status.level,\n          over: status.over,\n        })\n      }\n      const fold = (rows: ReturnType<UsageStore['aggregate']>): GroupRow[] =>\n        rows.map((r) => ({\n          key: r.model !== '*' ? r.model : r.user,\n          calls: r.calls,\n          inTok: r.in + r.cw,\n          outTok: r.out,\n          cacheRead: r.cr,\n          cacheWrite: r.cw,\n          cost: r.cost,\n        }))\n      // Members that metered activity but have no budgets file entry.\n      for (const row of store.aggregate('month', 'member')) {\n        if (seen.has(row.user)) continue\n        seen.add(row.user)\n        const totals = store.totalsFor(row.user)\n        memberRows.push({\n          name: row.user,\n          todayCost: totals.todayCost,\n          todayTokens: totals.todayTokens,\n          monthCost: totals.monthCost,\n          monthTokens: totals.monthTokens,\n          level: 0,\n          over: false,\n        })\n      }\n      memberRows.sort((a, b) => b.monthCost - a.monthCost)\n      const now = new Date()\n      return {\n        currency,\n        enforce,\n        generatedAt: now.getTime(),\n        dayKey: store.todayKey(),\n        monthKey: store.monthKey(),\n        members: memberRows,\n        todayByModel: fold(store.aggregate('today', 'model')),\n        monthByModel: fold(store.aggregate('month', 'model')),\n      }\n    },\n  }\n  Object.defineProperty(service, 'typertRemote', {\n    configurable: false,\n    enumerable: false,\n    writable: false,\n    value: { service, serviceKey: 'teamCost', namespace: 'teamCost' },\n  })\n  return service\n}\n\nexport interface TeamCostService {\n  getState(): Promise<TeamCostState>\n}\n"
    }
